{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    allocs = [seg['minimum'] for seg in segments]
    remaining = budget - sum(allocs)
    while remaining > 0:
        best_idx = -1
        best_imp = -1
        for i, seg in enumerate(segments):
            if allocs[i] < seg['capacity'] and seg['importance'] > best_imp:
                best_imp = seg['importance']
                best_idx = i
        if best_idx == -1:
            break
        allocs[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocs[i] for i in range(n)}
    return {'allocations': allocs, 'by_name': by_name, 'total': budget}"
}
